import{_ as l,a0 as d,w as s,s as p,I as i,x as t,a1 as n,A as o,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"将 Fedora Linux 系统添加到企业域中 | LCTT x X-CMD","titleTemplate":false,"description":"将 Fedora Linux 系统添加到企业域中 | LCTT (202105) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"将 Fedora Linux 系统添加到企业域中 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"将 Fedora Linux 系统添加到企业域中 | LCTT (202105) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202105/20210521 Joining Fedora Linux to an enterprise domain","title":"将 Fedora Linux 系统添加到企业域中","tag":"202105","desc":""},"relativePath":"202105/20210521 Joining Fedora Linux to an enterprise domain.md","filePath":"[post].md"}'),m={name:"202105/20210521 Joining Fedora Linux to an enterprise domain.md"};function u(f,e,g,x,L,b){const r=d("Link");return s(),p("div",null,[e[27]||(e[27]=i("h1",{id:"将-fedora-linux-系统添加到企业域中",tabindex:"-1"},[t("将 Fedora Linux 系统添加到企业域中 "),i("a",{class:"header-anchor",href:"#将-fedora-linux-系统添加到企业域中","aria-label":"Permalink to “将 Fedora Linux 系统添加到企业域中”"},"​")],-1)),e[28]||(e[28]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202105/26/120149o01pzllgw119w66l.jpg",alt:""})],-1)),e[29]||(e[29]=i("p",null,"在企业互联网场景中，一般情况下最广泛使用的基于 Linux 的操作系统是 Red Hat Enterprise Linux（RHEL），它主要用于服务器，但也可以用作工作站。Fedora linux 其实也是工作站系统的一个很好的选择，它提供了许多在企业环境中工作的特性，使管理成为一项简单的任务。",-1)),i("p",null,[e[3]||(e[3]=t("当你的工作网络中有许多机器时，你需要一种以集中方式管理用户和机器的方法。",-1)),n(r,{href:"https://www.freeipa.org/page/Main_Page"},{default:o(()=>[...e[0]||(e[0]=[t("FreeIPA",-1)])]),_:1}),e[4]||(e[4]=t(" 和 ",-1)),i("ruby",null,[n(r,{href:"https://en.wikipedia.org/wiki/Active_Directory"},{default:o(()=>[...e[1]||(e[1]=[t("活动目录",-1)])]),_:1}),e[2]||(e[2]=i("rt",null,"Active Directory",-1))]),e[5]||(e[5]=t(" 就是用于这个任务的技术。它们允许系统管理员使用网络中所有实体的目录来管理大量的机器。",-1))]),e[30]||(e[30]=a('<h3 id="fedora-中的活动目录" tabindex="-1">Fedora 中的活动目录 <a class="header-anchor" href="#fedora-中的活动目录" aria-label="Permalink to “Fedora 中的活动目录”">​</a></h3><p>活动目录在公司环境中非常常见。Fedora 和 RHEL 通过使用 SSSD （<ruby> 系统安全服务守护进程 <rt>System Security Services Daemon</rt></ruby>）与 FreeIPA 或活动目录等服务很好地集成。SSSD 是一种访问远程目录和身份验证机制的系统服务。使用此软件的计算机能够使用远程凭据进行身份验证，并访问该目录网络中可用的其他服务。</p><p>要加入域网络，你需要域管理员的权限才能添加计算机。可以通过在域凭据上设置特殊权限或代表你对该计算机进行预配置。Fedora Linux 有一个在安装时配置机器的选项，叫做<ruby>企业登录<rt>Enterprise Login</rt></ruby>。如果你的计算机网络自动配置为企业域网络，那么你可以直接使用域凭据登录。</p><p><img src="https://lh5.googleusercontent.com/aIRYn2TDgaaUrErzBV_KPVgpm94OrVgySlwqlI3VsotslWKN5UnLQ0VYjESSFB12aZWf_UnbmOOwa_rcxvRoI-MB6gFaw8p-RgBP9Lswnb2YV3iIlQ8YeXgpwJC_-B5tPrFTfUe_" alt=""></p><p>如果你的配置不是自动的，或者你已经安装了 Fedora Linux，你可以通过以下几个配置步骤加入一个活动目录域：</p><ol><li>设置此计算机的 DNS。要连接到目录服务，首先需要能够解析目录域名。如果你的网络使用 DHCP 设置正确的 DNS，则可以跳过此步骤。</li><li>更改你的计算机名称，以反映它将是新域的一部分。编辑文件 <code>/etc/hostname</code>，并将机器名更改为 <code>machinename.my_domain</code>。</li><li>通过执行以下命令加入域：<code>sudo realm join my_domain -v</code>（ 用域名称替换 <code>my_domain</code>）。</li></ol><p>运行此命令后，系统将请求允许加入该域中新计算机的用户的凭据。如果进程中没有错误，则机器将成为域的一部分。</p><p><img src="https://lh6.googleusercontent.com/DVvr7cHuZxvgqhAHk9v7jAYSER7VSP1G7CJ1xHx1kT5ZS-v1yt3rKMmwk9JhsLnYGfwAjOPPpSC2BGTpZtAdKrnx7XLUWgOZBhFFwB6SL7vR_q_2N1c_OGYp7YmNLRk7oRW8IEVB" alt=""></p><p>现在，此计算机已成为你的域的一部分，你可以：</p><ul><li>使用域用户名登录到计算机</li><li>获取 kerberos 票据以访问域网络中的不同服务</li><li>访问其他服务，具体取决于域的配置方式</li></ul><h3 id="使用-fleet-commander-管理-fedora-linux" tabindex="-1">使用 Fleet Commander 管理 Fedora Linux <a class="header-anchor" href="#使用-fleet-commander-管理-fedora-linux" aria-label="Permalink to “使用 Fleet Commander 管理 Fedora Linux”">​</a></h3><p>现在这台计算机已经是你的域的一部分了，你可以使用活动目录的域管理员工具来管理它。由于你的计算机没有运行 Windows，因此你只能进行身份验证以及访问网络和目录服务。无法在此计算机上设置与桌面相关的配置。</p>',12)),i("p",null,[e[7]||(e[7]=t("幸运的是，Fedora 有个工具叫 ",-1)),n(r,{href:"https://fleet-commander.org/"},{default:o(()=>[...e[6]||(e[6]=[t("Fleet Commander",-1)])]),_:1}),e[8]||(e[8]=t("。",-1))]),e[31]||(e[31]=a('<h4 id="创建配置" tabindex="-1">创建配置 <a class="header-anchor" href="#创建配置" aria-label="Permalink to “创建配置”">​</a></h4><p>Fleet Commander 是一个管理工具，允许你为网络中的所有 Fedora Linux 机器设置桌面配置文件。</p><p>这意味着，你可以简单地为 GNOME 桌面、Firefox、Chrome、LibreOffice 和其他支持的软件设置任何配置，然后在登录到选定的用户/组/计算机时以细粒度的方式应用该配置。</p><p><img src="https://lh6.googleusercontent.com/ATeNp5niX37MW7ARiMVSkqe9Vr5Fv4IN6eUW5xf1UPO0AMO1DxXLypw0CbqTNOfzLJYDM18ggc7Mrh3LZK8Foh80K1WjSW9LHQD081BbJg0owQJj_ZQdICLr0tGILmBRco-xbq92" alt=""></p><p>要使用这个工具首先安装 <code>fleet-commander-admin</code> 软件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install fleet-commander-admin</span></span></code></pre></div>',6)),i("p",null,[e[10]||(e[10]=t("然后，用浏览器访问 ",-1)),n(r,{href:"http://localhost:9090/"},{default:o(()=>[...e[9]||(e[9]=[t("http://localhost:9090",-1)])]),_:1}),e[11]||(e[11]=t(" 来登录。在左边的菜单中，点击 “Fleet Commander”。",-1))]),e[32]||(e[32]=a('<p>Fleet Commander 有一个工具，可以使用“实时会话”机制直观地设置配置概要文件。它运行一个虚拟机，作为基本机器的模板。你需要手动进行所需的配置更改。然后检查所有配置更改，选择要添加到配置文件中的更改，然后部署它。</p><h4 id="管理客户端" tabindex="-1">管理客户端 <a class="header-anchor" href="#管理客户端" aria-label="Permalink to “管理客户端”">​</a></h4><p>在每个 Fedora Linux 或 RHEL 机器中，你都需要安装 Fleet Commander 客户端服务。此服务在用户登录时激活。它在域中搜索应用于当前用户/计算机的配置文件，并应用这个配置。</p><p>安装 <code>fleet-commander-client</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install fleet-commander-client</span></span></code></pre></div><p>软件将自动检测机器是否是域的一部分。当用户登录时，它将使用应用于该用户的配置文件来设置会话。</p><hr>',7)),i("p",null,[e[13]||(e[13]=t("via: ",-1)),n(r,{href:"https://fedoramagazine.org/join-fedora-linux-enterprise-domain/"},{default:o(()=>[...e[12]||(e[12]=[t("https://fedoramagazine.org/join-fedora-linux-enterprise-domain/",-1)])]),_:1})]),i("p",null,[e[18]||(e[18]=t("作者：",-1)),n(r,{href:"https://fedoramagazine.org/author/ogutierrez/"},{default:o(()=>[...e[14]||(e[14]=[t("ogutierrez",-1)])]),_:1}),e[19]||(e[19]=t(" 选题：",-1)),n(r,{href:"https://github.com/lujun9972"},{default:o(()=>[...e[15]||(e[15]=[t("lujun9972",-1)])]),_:1}),e[20]||(e[20]=t(" 译者：",-1)),n(r,{href:"https://github.com/Chao-zhi"},{default:o(()=>[...e[16]||(e[16]=[t("Chao-zhi",-1)])]),_:1}),e[21]||(e[21]=t(" 校对：",-1)),n(r,{href:"https://github.com/wxy"},{default:o(()=>[...e[17]||(e[17]=[t("wxy",-1)])]),_:1})]),i("p",null,[e[24]||(e[24]=t("本文由 ",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[22]||(e[22]=[t("LCTT",-1)])]),_:1}),e[25]||(e[25]=t(" 原创编译，",-1)),n(r,{href:"https://linux.cn/"},{default:o(()=>[...e[23]||(e[23]=[t("Linux中国",-1)])]),_:1}),e[26]||(e[26]=t(" 荣誉推出",-1))])])}const F=l(m,[["render",u]]);export{C as __pageData,F as default};
